UPDATE SYS_MULTI_LANGUAGE_RESOURCE SET RESOURCE_KEY = 'menu.FACTORY_IVT_MOVE_ORDER'                    WHERE RESOURCE_KEY = 'menu.FACTORY_IVT_MOVE_ODER';
