UPDATE SYS_MULTI_LANGUAGE_RESOURCE SET RESOURCE_KEY = 'menu.QMS_REP_ITEM_STATUS'                       WHERE RESOURCE_KEY = 'menu.QMS_REP_ITEM_STATUS.js';
