UPDATE SYS_MULTI_LANGUAGE_RESOURCE SET RESOURCE_KEY = 'menu.SYSTEM2_COMMON'                            WHERE RESOURCE_KEY = 'menu.ITOOLC4390041D17C4B26DE5D5C9B729B7498';

-- ── 메뉴 본체 — 새 ID + PROGRAM_ID=구 ID 보존 (신규 DB는 빈 테이블이라 무해 no-op) ──
UPDATE SYS_MENU SET MENU_ID = 'EES_EPT_OVERALL_EQUIPMENT_EFFECTIVENESS', UI_ID = 'EES_EPT_OVERALL_EQUIPMENT_EFFECTIVENESS', PROGRAM_ID = 'EES_EPT_OVERALL_EQUIPMENT_EFFECIVENESS' WHERE MENU_ID = 'EES_EPT_OVERALL_EQUIPMENT_EFFECIVENESS';
